body:
Adding in a generic transaction that will wrap an entire set of logic in a transaction

An example:

Any step here that would result in an error, such as updating from downloading state to downloaded state, would roll the entirety of the transaction back.

```golang
err := store.Transaction(ctx, func(ctx context.Context, tx *sql.Tx) error {
	path := "Title/Title.mkv"
	movie := storage.Movie{
		Movie: model.Movie{
			ID:              1,
			Path:            &path,
			Monitored:       1,
			MovieFileID:     ptr(int32(1)),
			MovieMetadataID: ptr(int32(1)),
		},
	}

	movieID, err := store.CreateMovie(ctx, movie, storage.MovieStateMissing, tx)
	if err != nil {
		return err
	}

	err = store.UpdateMovieState(ctx, movieID, storage.MovieStateDownloading, &storage.MovieStateMetadata{
		DownloadID:       ptr("1"),
		DownloadClientID: ptr(int32(1)),
	}, tx)
	if err != nil {
		return err
	}

	err = store.UpdateMovieState(ctx, movieID, storage.MovieStateDownloaded, nil, tx)
	if err != nil {
		return err
	}

	return nil
})
```

